<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'

type Product = { id: string | number; name: string; category: string; price: number; stock: number; icon: string; tone: string; minimumStock?: number; imageUrl?: string | null; expiryDate?: string | null; discountType?: string | null; discountValue?: number }
type CartLine = Product & { quantity: number }
type Receipt = { invoiceNo: string; createdAt: string; subtotal: number; tax: number; discount: number; total: number; payment: string; reference?: string; customer?: string; cashier?: string; lines: CartLine[] }

const activeView = ref('Overview')
const search = ref('')
const selectedCategory = ref('All items')
const payment = ref('Cash')
const paymentReference = ref('')
const discount = ref(0)
const completed = ref(false)
const products = ref<Product[]>([
  { id: 1, name: 'Vendora Cold Brew', category: 'Drinks', price: 4.5, stock: 34, icon: '☕', tone: 'coffee' },
  { id: 2, name: 'Matcha Oat Latte', category: 'Drinks', price: 5.25, stock: 18, icon: '🍵', tone: 'matcha' },
  { id: 3, name: 'Sparkling Water', category: 'Drinks', price: 2, stock: 48, icon: '◌', tone: 'water' },
  { id: 4, name: 'Sea Salt Chips', category: 'Snacks', price: 2.75, stock: 12, icon: '◒', tone: 'chips' },
  { id: 5, name: 'Almond Croissant', category: 'Bakery', price: 3.95, stock: 7, icon: '🥐', tone: 'croissant' },
  { id: 6, name: 'Berry Yogurt Bowl', category: 'Food', price: 6.5, stock: 9, icon: '◉', tone: 'berry' },
  { id: 7, name: 'Avocado Toast', category: 'Food', price: 7.75, stock: 15, icon: '◈', tone: 'avocado' },
  { id: 8, name: 'Chocolate Cookie', category: 'Bakery', price: 2.25, stock: 22, icon: '●', tone: 'cookie' },
])
const cart = ref<CartLine[]>([{ ...products.value[0], quantity: 1 }, { ...products.value[3], quantity: 2 }])
const categories = computed(() => ['All items', ...new Set(products.value.map((item) => item.category))])
const nav = [['Overview','⌘'], ['Sell','▣'], ['Orders','◫'], ['Products','◇'], ['Inventory','▤'], ['Customers','♙'], ['Analytics','◔'], ['Team','♧']]
const filteredProducts = computed(() => products.value.filter((item) => (selectedCategory.value === 'All items' || item.category === selectedCategory.value) && item.name.toLowerCase().includes(search.value.toLowerCase())))
const subtotal = computed(() => cart.value.reduce((sum, item) => sum + item.price * item.quantity, 0))
const tax = computed(() => subtotal.value * 0.08)
const total = computed(() => Math.max(0, subtotal.value + tax.value - discount.value))
const apiUrl = import.meta.env.VITE_API_URL ?? 'http://localhost:3000/api'
const apiStatus = ref<'demo' | 'connected'>('demo')
const showProductForm = ref(false)
const processing = ref(false)
const receipt = ref<Receipt | null>(null)
const productForm = ref({ name: '', category: 'General', price: 0, stock: 0, expiryDate: '', imageUrl: '', discountType: '', discountValue: 0 })
const orders = ref<any[]>([])
const inventory = ref<any[]>([])
const customers = ref<any[]>([])
const team = ref<any[]>([])
const analytics = ref<any | null>(null)
const screenLoading = ref(false)
const screenMessage = ref('')
const selectedCustomerId = ref('')
const showCustomerPicker = ref(false)
const currentUser = ref<any>(JSON.parse(localStorage.getItem('vendorax-user') ?? 'null'))
const money = (value: number) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(value)
function productPrice(product: Product) { const discount = product.discountType === 'PERCENT' ? product.price * Number(product.discountValue ?? 0) / 100 : product.discountType === 'FIXED' ? Number(product.discountValue ?? 0) : 0; return Math.max(0, product.price - discount) }
function discountTag(product: Product) { return product.discountType === 'PERCENT' ? `${product.discountValue}% OFF` : product.discountType === 'FIXED' ? `${money(Number(product.discountValue))} OFF` : '' }
function addToCart(product: Product) { const line = cart.value.find((item) => item.id === product.id); if (line) line.quantity++; else cart.value.push({ ...product, price: productPrice(product), quantity: 1 }); completed.value = false }
function changeQuantity(id: string | number, amount: number) { const line = cart.value.find((item) => item.id === id); if (!line || (amount > 0 && line.quantity >= line.stock)) return; line.quantity += amount; if (line.quantity < 1) cart.value = cart.value.filter((item) => item.id !== id) }
function removeFromCart(id: string | number) { cart.value = cart.value.filter((item) => item.id !== id) }
function expiryLabel(value?: string | null) { if (!value) return ''; const days = Math.ceil((new Date(value).getTime() - Date.now()) / 86400000); return days < 0 ? 'Expired' : days <= 30 ? `Expires in ${days}d` : `Expires ${new Date(value).toLocaleDateString()}` }
function selectImage(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (!file.type.startsWith('image/') || file.size > 2 * 1024 * 1024) return alert('Image JPG/PNG/WebP aur 2MB se kam honi chahiye.'); const reader = new FileReader(); reader.onload = () => { productForm.value.imageUrl = String(reader.result) }; reader.readAsDataURL(file) }
const selectedCustomer = computed(() => customers.value.find((customer) => customer.id === selectedCustomerId.value))
async function addProduct() { if (!productForm.value.name || productForm.value.price <= 0) return; const draft = { ...productForm.value }; try { if (apiStatus.value === 'connected') { const response = await fetch(`${apiUrl}/products`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: draft.name, category: draft.category || 'General', retailPrice: draft.price, openingStock: draft.stock, expiryDate: draft.expiryDate || null, imageUrl: draft.imageUrl || null, discountType: draft.discountType || null, discountValue: draft.discountValue || 0 }) }); if (!response.ok) throw new Error('Could not add product'); await loadProducts() } else products.value.unshift({ id: `local-${Date.now()}`, name: draft.name, category: draft.category || 'General', price: Number(draft.price), stock: Number(draft.stock), minimumStock: 10, icon: '✦', tone: 'water', expiryDate: draft.expiryDate, imageUrl: draft.imageUrl, discountType: draft.discountType, discountValue: draft.discountValue }); productForm.value = { name: '', category: 'General', price: 0, stock: 0, expiryDate: '', imageUrl: '', discountType: '', discountValue: 0 }; showProductForm.value = false } catch { alert('Product save nahi hua. API/database connection check karein.') } }
async function loadProducts() { try { const response = await fetch(`${apiUrl}/products`); if (!response.ok) return; const rows = await response.json(); products.value = rows.map((item: any, index: number) => ({ id: item.id, name: item.name, category: item.category?.name ?? 'General', price: Number(item.retailPrice), stock: item.stock?.quantity ?? 0, minimumStock: item.minimumStock, imageUrl: item.imageUrl, expiryDate: item.expiryDate, discountType: item.discountType, discountValue: Number(item.discountValue), icon: ['☕','🍵','◌','◒','🥐'][index % 5], tone: ['coffee','matcha','water','chips','croissant'][index % 5] })); apiStatus.value = 'connected' } catch { apiStatus.value = 'demo' } }
async function loadScreen(view = activeView.value) { if (!['Orders', 'Inventory', 'Customers', 'Analytics', 'Team'].includes(view)) return; screenLoading.value = true; screenMessage.value = ''; try { const route: Record<string, string> = { Orders: 'sales', Inventory: 'inventory/stock', Customers: 'customers', Analytics: 'dashboard', Team: 'users' }; const response = await fetch(`${apiUrl}/${route[view]}`); if (!response.ok) throw new Error('Request failed'); const data = await response.json(); if (view === 'Orders') orders.value = data; if (view === 'Inventory') inventory.value = data; if (view === 'Customers') customers.value = data; if (view === 'Analytics') analytics.value = data; if (view === 'Team') team.value = data; } catch { screenMessage.value = 'Live data load nahi hua. Backend connection check karein.' } finally { screenLoading.value = false } }
async function adjustStock(item: any, amount: number) { try { const response = await fetch(`${apiUrl}/inventory/adjust`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ productId: item.productId, quantity: amount, notes: 'VendoraX dashboard adjustment' }) }); if (!response.ok) throw new Error('Adjustment failed'); await loadScreen('Inventory'); await loadProducts(); } catch { alert('Stock adjustment save nahi hua.') } }
async function addCustomer() { const name = window.prompt('Customer name'); if (!name) return; const phone = window.prompt('Phone number (optional)') ?? ''; try { const response = await fetch(`${apiUrl}/customers`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name, phone }) }); if (!response.ok) throw new Error('Customer create failed'); const customer = await response.json(); selectedCustomerId.value = customer.id; await loadScreen('Customers'); } catch { alert('Customer save nahi hua.') } }
async function addTeamMember() { const firstName = window.prompt('Team member name'); if (!firstName) return; const email = window.prompt('Email address'); if (!email) return; const password = window.prompt('Login password (minimum 6 characters)'); if (!password) return; try { const response = await fetch(`${apiUrl}/users`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ firstName, email, password, role: 'CASHIER' }) }); if (!response.ok) throw new Error('Member create failed'); await loadScreen('Team'); } catch { alert('Team member save nahi hua.') } }
async function loginSalesperson() { const email = window.prompt('Salesperson email'); if (!email) return; const password = window.prompt('Password'); if (!password) return; try { const response = await fetch(`${apiUrl}/auth/login`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ email, password }) }); if (!response.ok) throw new Error('Login failed'); const data = await response.json(); currentUser.value = data.user; localStorage.setItem('vendorax-user', JSON.stringify(data.user)); } catch { alert('Login failed. Email aur password check karein.') } }
function logoutSalesperson() { currentUser.value = null; localStorage.removeItem('vendorax-user') }
async function checkout() { if (!cart.value.length || processing.value) return; if (apiStatus.value === 'connected' && !currentUser.value) { await loginSalesperson(); if (!currentUser.value) return; } processing.value = true; const lines = cart.value.map((item) => ({ ...item })); try { if (apiStatus.value === 'connected' && lines.every((item) => typeof item.id === 'string')) { const response = await fetch(`${apiUrl}/sales`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ paymentMode: payment.value.toUpperCase(), paymentReference: paymentReference.value, discount: discount.value, customerId: selectedCustomerId.value || undefined, userId: currentUser.value?.id, items: lines.map((item) => ({ productId: item.id, quantity: item.quantity, unitPrice: item.price })) }) }); if (!response.ok) throw new Error('Sale could not be saved'); const sale = await response.json(); receipt.value = { invoiceNo: sale.invoiceNo, createdAt: new Date().toLocaleString(), subtotal: subtotal.value, tax: Number(sale.tax), discount: Number(sale.discount), total: Number(sale.totalAmount), payment: payment.value, reference: paymentReference.value, customer: selectedCustomer.value?.name || 'Walk-in customer', cashier: currentUser.value?.firstName, lines } } else receipt.value = { invoiceNo: `VX-${Date.now().toString().slice(-6)}`, createdAt: new Date().toLocaleString(), subtotal: subtotal.value, tax: tax.value, discount: discount.value, total: total.value, payment: payment.value, reference: paymentReference.value, customer: selectedCustomer.value?.name || 'Walk-in customer', cashier: currentUser.value?.firstName, lines }; completed.value = true; lines.forEach((line) => { const p = products.value.find((item) => item.id === line.id); if (p) p.stock -= line.quantity }); cart.value = []; discount.value = 0; selectedCustomerId.value = ''; paymentReference.value = '' } catch { alert('Sale save nahi hui. API/database connection check karein.') } finally { processing.value = false } }
function printReceipt() { window.print() }
onMounted(() => { loadProducts(); loadScreen(); loadScreen('Customers') })
watch(activeView, (view) => loadScreen(view))
</script>

<template>
  <main class="app-shell">
    <aside class="sidebar">
      <div class="brand"><span class="brand-mark">V</span><span>Vendora<span>X</span></span></div>
      <div class="store"><i>✦</i><div><b>Northstar Market</b><small>Downtown · Register 01</small></div><span>⌄</span></div>
      <nav><button v-for="item in nav" :key="item[0]" :class="{active: activeView === item[0]}" @click="activeView = item[0]"><i>{{ item[1] }}</i><span>{{ item[0] }}</span><em v-if="item[0] === 'Orders'">4</em></button></nav>
      <div class="side-bottom"><button><i>?</i><span>Help center</span></button><div class="user"><strong>SK</strong><div><b>Sofia Kaif</b><small>Store manager</small></div><span>⋮</span></div></div>
    </aside>
    <section class="workspace">
      <header><div><p>Tuesday, March 12</p><h1>{{ activeView === 'Overview' ? 'Good morning, Sofia' : activeView }}</h1></div><div class="header-actions"><button v-if="currentUser" class="user-login" @click="logoutSalesperson">{{ currentUser.firstName }} · Logout</button><button v-else class="user-login" @click="loginSalesperson">Cashier login</button><button class="utility">⌕</button><button class="new-sale" @click="activeView = 'Sell'">+ New sale <kbd>⌘ K</kbd></button></div></header>
      <template v-if="activeView === 'Overview'">
        <section class="stats">
          <article><i class="mint">↗</i><div><span>Today's sales</span><b>$2,846.50</b><small class="up">↑ 12.5% <em>vs. yesterday</em></small></div><svg class="spark green" viewBox="0 0 100 40"><path d="M0 33C14 21 18 31 29 19S44 28 52 13S67 20 76 8S88 8 100 1"/></svg></article>
          <article><i class="purple">▣</i><div><span>Orders</span><b>128</b><small class="up">↑ 8.2% <em>vs. yesterday</em></small></div><svg class="spark violet" viewBox="0 0 100 40"><path d="M0 30C15 26 17 34 29 18S42 27 53 19S68 28 76 9S92 21 100 3"/></svg></article>
          <article><i class="amber">◎</i><div><span>Average order</span><b>$22.24</b><small class="down">↓ 2.4% <em>vs. yesterday</em></small></div><svg class="spark orange" viewBox="0 0 100 40"><path d="M0 10C15 17 17 4 29 17S43 11 52 23S66 12 75 25S91 18 100 32"/></svg></article>
          <article><i class="blue">◒</i><div><span>Low stock items</span><b>9</b><small class="warn">Needs attention</small></div><button class="arrow" @click="activeView='Inventory'">→</button></article>
        </section>
        <section class="dashboard">
          <article class="panel sales"><div class="panel-head"><div><h2>Sales overview</h2><p>Revenue performance this week</p></div><button>This week ⌄</button></div><div class="chart"><div class="y-labels"><span>$1.2k</span><span>$900</span><span>$600</span><span>$300</span><span>$0</span></div><div class="bars"><div v-for="(height,index) in [52,68,44,86,61,92,70]" :key="index"><i :style="{height: height + '%'}"></i><span>{{ ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][index] }}</span></div></div><aside><b>$6,482.90</b><span>Total sales</span><small>↑ 14.8%</small></aside></div></article>
          <article class="panel channels"><div class="panel-head"><div><h2>Sales channels</h2><p>Today’s transaction mix</p></div><button class="more">•••</button></div><div class="channel-body"><div class="donut"><div><b>128</b><span>orders</span></div></div><div class="legend"><p><i class="direct"></i>In-store <b>76%</b><small>97 orders</small></p><p><i class="pickup"></i>Pickup <b>16%</b><small>20 orders</small></p><p><i class="online"></i>Online <b>8%</b><small>11 orders</small></p></div></div></article>
          <article class="panel top-products"><div class="panel-head"><div><h2>Top products</h2><p>By units sold today</p></div><button class="link" @click="activeView='Products'">View all →</button></div><div v-for="(product,index) in products.slice(0,4)" :key="product.id" class="top-row"><span>0{{index+1}}</span><i :class="product.tone">{{ product.icon }}</i><div><b>{{product.name}}</b><small>{{[42,36,29,24][index]}} sold</small></div><strong>{{money(product.price * [42,36,29,24][index])}}</strong><em><i :style="{width:[92,78,63,51][index]+'%'}"></i></em></div></article>
          <article class="panel activity"><div class="panel-head"><div><h2>Recent activity</h2><p>Live store updates</p></div><button class="more">•••</button></div><div class="activity-row"><i class="done">✓</i><div><b>Order #VX-10428 completed</b><small>Card payment · $24.50</small></div><time>2 min</time></div><div class="activity-row"><i class="low">!</i><div><b>Low stock: Almond Croissant</b><small>7 units remaining</small></div><time>18 min</time></div><div class="activity-row"><i class="added">+</i><div><b>New customer added</b><small>Amelia Roberts</small></div><time>34 min</time></div><button class="view-all">View all activity</button></article>
        </section>
      </template>
      <template v-else-if="activeView === 'Sell'">
        <section class="pos">
          <article class="panel catalog"><div class="catalog-tools"><label><span>⌕</span><input v-model="search" placeholder="Search products or scan barcode"><kbd>⌘ F</kbd></label><button @click="showProductForm=true">+ Product</button></div><div class="pos-meta"><span :class="apiStatus">{{apiStatus === 'connected' ? '● Live API catalog' : '● Demo catalog — API offline'}}</span><button @click="loadProducts">↻ Refresh</button></div><div class="categories"><button v-for="category in categories" :key="category" :class="{selected: category===selectedCategory}" @click="selectedCategory=category">{{category}}</button></div><div class="product-grid"><button v-for="product in filteredProducts" :key="product.id" :disabled="product.stock < 1 || expiryLabel(product.expiryDate)==='Expired'" @click="addToCart(product)"><i v-if="!product.imageUrl" :class="product.tone">{{product.icon}}</i><img v-else :src="product.imageUrl" :alt="product.name"><b>{{product.name}}</b><span><s v-if="discountTag(product)">{{money(product.price)}}</s> {{money(productPrice(product))}}</span><small :class="{lowText: product.stock <= (product.minimumStock ?? 10)}">{{product.stock < 1 ? 'Out of stock' : expiryLabel(product.expiryDate)==='Expired' ? 'Expired — sale blocked' : product.stock + ' in stock'}} {{expiryLabel(product.expiryDate) && expiryLabel(product.expiryDate)!=='Expired' ? '· ' + expiryLabel(product.expiryDate) : ''}}</small><mark v-if="discountTag(product)">{{discountTag(product)}}</mark><em>+</em></button></div></article>
          <aside class="panel checkout"><div class="checkout-head"><div><p>CURRENT ORDER</p><h2>New sale <span>#VX-10429</span></h2></div><button class="more">•••</button></div><div class="customer"><i>♙</i><div><b>{{selectedCustomer?.name || 'Walk-in customer'}}</b><small>{{selectedCustomer?.phone || 'Add/select customer for this sale'}}</small></div><button @click="showCustomerPicker=!showCustomerPicker">+</button></div><div v-if="showCustomerPicker" class="customer-picker"><button @click="selectedCustomerId='';showCustomerPicker=false">Walk-in customer</button><button v-for="customer in customers" :key="customer.id" @click="selectedCustomerId=customer.id;showCustomerPicker=false">{{customer.name}} <small>{{customer.phone}}</small></button><button class="add-customer" @click="addCustomer">+ New customer</button></div><div class="cart"><p v-if="!cart.length" class="empty">Your cart is waiting.<br>Select products to begin.</p><div v-for="line in cart" :key="line.id" class="cart-line"><i v-if="!line.imageUrl" :class="line.tone">{{line.icon}}</i><img v-else :src="line.imageUrl" :alt="line.name"><div><b>{{line.name}}</b><small>{{money(line.price)}} each</small></div><label><button @click="changeQuantity(line.id,-1)">−</button><span>{{line.quantity}}</span><button @click="changeQuantity(line.id,1)">+</button></label><strong>{{money(line.price*line.quantity)}}</strong><button class="remove-line" @click="removeFromCart(line.id)">×</button></div></div><div class="summary"><p><span>Subtotal</span><b>{{money(subtotal)}}</b></p><p><span>Tax <small>(8%)</small></span><b>{{money(tax)}}</b></p><button @click="discount=discount?0:2"><span>⌁ {{discount?'Remove bill discount':'Add bill discount'}}</span><b>{{discount?'−'+money(discount):'+'}}</b></button><div><span>Total</span><b>{{money(total)}}</b></div></div><div class="payments"><button v-for="method in ['Cash','Visa / Mastercard','Bank Account','EasyPaisa','JazzCash','Credit']" :key="method" :class="{selected:payment===method}" @click="payment=method"><i>{{method==='Cash'?'$':method==='Visa / Mastercard'?'▣':method==='EasyPaisa'?'E':'₨'}}</i>{{method}}</button></div><input v-if="payment !== 'Cash'" v-model.trim="paymentReference" class="payment-reference" :placeholder="payment === 'Credit' ? 'Credit notes / due date' : 'Transaction, account or card reference'"><p class="cashier">{{currentUser ? 'Cashier: ' + currentUser.firstName : 'Cashier login required'}}</p><button class="charge" :disabled="!cart.length || processing" @click="checkout">{{processing?'Saving sale…':`Charge ${money(total)}`}} <span>→</span></button></aside>
        </section>
      </template>
      <section v-else-if="activeView === 'Products'" class="panel data-screen"><div class="screen-head"><div><p>CATALOG</p><h2>Products</h2></div><button class="new-sale" @click="showProductForm=true">+ Add product</button></div><div v-if="!products.length" class="empty-state">No products yet. Add your first product to start selling.</div><div v-else class="data-list"><article v-for="product in products" :key="product.id"><i v-if="!product.imageUrl" :class="product.tone">{{ product.icon }}</i><img v-else class="list-image" :src="product.imageUrl" :alt="product.name"><div><b>{{ product.name }}</b><small>{{ product.category }} · {{ product.stock }} in stock {{ expiryLabel(product.expiryDate) ? '· ' + expiryLabel(product.expiryDate) : '' }}</small></div><strong>{{ money(product.price) }}</strong><button @click="addToCart(product); activeView='Sell'">Sell →</button></article></div></section>
      <section v-else-if="activeView === 'Orders'" class="panel data-screen"><div class="screen-head"><div><p>SALES HISTORY</p><h2>Orders</h2></div><button class="utility" @click="loadScreen('Orders')">↻</button></div><p v-if="screenLoading">Loading orders…</p><p v-else-if="screenMessage" class="error">{{ screenMessage }}</p><div v-else-if="!orders.length" class="empty-state">No completed orders yet. Create a sale from the Sell screen.</div><div v-else class="data-list"><article v-for="order in orders" :key="order.id"><i class="mint">✓</i><div><b>{{ order.invoiceNo }}</b><small>{{ new Date(order.createdAt).toLocaleString() }} · {{ order.items.length }} item(s)</small></div><strong>{{ money(Number(order.totalAmount)) }}</strong><span class="badge">{{ order.paymentMode }}</span></article></div></section>
      <section v-else-if="activeView === 'Inventory'" class="panel data-screen"><div class="screen-head"><div><p>STOCK & EXPIRY CONTROL</p><h2>Inventory</h2></div><button class="utility" @click="loadScreen('Inventory')">↻</button></div><p v-if="screenLoading">Loading inventory…</p><p v-else-if="screenMessage" class="error">{{ screenMessage }}</p><div v-else-if="!inventory.length" class="empty-state">No inventory yet. Add a product with opening stock.</div><div v-else class="data-list"><article v-for="item in inventory" :key="item.id"><i :class="item.quantity <= item.product.minimumStock ? 'amber' : 'mint'">▤</i><div><b>{{ item.product.name }}</b><small>{{ item.product.category?.name ?? 'General' }} · minimum {{ item.product.minimumStock }} <em v-if="expiryLabel(item.product.expiryDate)" :class="{expired: expiryLabel(item.product.expiryDate)==='Expired'}">· {{ expiryLabel(item.product.expiryDate) }}</em></small></div><strong>{{ item.quantity }} units</strong><span class="stock-actions"><button @click="adjustStock(item, -1)">−</button><button @click="adjustStock(item, 1)">+</button></span></article></div></section>
      <section v-else-if="activeView === 'Customers'" class="panel data-screen"><div class="screen-head"><div><p>CUSTOMER DIRECTORY</p><h2>Customers</h2></div><button class="new-sale" @click="addCustomer">+ Add customer</button></div><p v-if="screenLoading">Loading customers…</p><p v-else-if="screenMessage" class="error">{{ screenMessage }}</p><div v-else-if="!customers.length" class="empty-state">No customers added yet.</div><div v-else class="data-list"><article v-for="customer in customers" :key="customer.id"><i class="purple">♙</i><div><b>{{ customer.name }}</b><small>{{ customer.phone || customer.email || 'No contact details' }}</small></div><strong>{{ customer._count.sales }} order(s)</strong></article></div></section>
      <section v-else-if="activeView === 'Analytics'" class="data-screen"><div class="screen-head"><div><p>LIVE BUSINESS METRICS</p><h2>Analytics</h2></div><button class="utility" @click="loadScreen('Analytics')">↻</button></div><p v-if="screenLoading">Loading analytics…</p><p v-else-if="screenMessage" class="error">{{ screenMessage }}</p><div v-else class="analytics-grid"><article class="panel"><span>Today's sales</span><b>{{ money(Number(analytics?.todaySales ?? 0)) }}</b></article><article class="panel"><span>Today's orders</span><b>{{ analytics?.todayOrders ?? 0 }}</b></article><article class="panel"><span>Active products</span><b>{{ analytics?.totalProducts ?? 0 }}</b></article><article class="panel"><span>Low stock items</span><b>{{ analytics?.lowStockCount ?? 0 }}</b></article></div></section>
      <section v-else-if="activeView === 'Team'" class="panel data-screen"><div class="screen-head"><div><p>STAFF ACCESS</p><h2>Team</h2></div><button class="new-sale" @click="addTeamMember">+ Add member</button></div><p v-if="screenLoading">Loading team…</p><p v-else-if="screenMessage" class="error">{{ screenMessage }}</p><div v-else-if="!team.length" class="empty-state">No team members added yet.</div><div v-else class="data-list"><article v-for="member in team" :key="member.id"><i class="blue">{{ member.firstName?.[0] ?? 'V' }}</i><div><b>{{ [member.firstName, member.lastName].filter(Boolean).join(' ') }}</b><small>{{ member.email }} · {{ member._count?.sales ?? 0 }} sales completed</small></div><strong>{{ member.role.replaceAll('_', ' ') }}</strong></article></div></section>
      <div v-if="showProductForm" class="modal-backdrop"><form class="modal" @submit.prevent="addProduct"><button type="button" class="close" @click="showProductForm=false">×</button><p>CATALOG MANAGEMENT</p><h2>Add new product</h2><label>Product name<input v-model.trim="productForm.name" required placeholder="e.g. Mineral Water 500ml"></label><label>Category<input v-model.trim="productForm.category" placeholder="Drinks"></label><div class="form-row"><label>Retail price<input v-model.number="productForm.price" type="number" min="0.01" step="0.01" required></label><label>Opening stock<input v-model.number="productForm.stock" type="number" min="0" required></label></div><label>Expiry date<input v-model="productForm.expiryDate" type="date"></label><div class="form-row"><label>Discount type<select v-model="productForm.discountType"><option value="">No discount</option><option value="PERCENT">Percentage (%)</option><option value="FIXED">Fixed amount</option></select></label><label>Discount value<input v-model.number="productForm.discountValue" type="number" min="0" step="0.01"></label></div><label>Product picture<input type="file" accept="image/png,image/jpeg,image/webp" @change="selectImage"></label><img v-if="productForm.imageUrl" class="image-preview" :src="productForm.imageUrl" alt="Product preview"><button class="new-sale" type="submit">Add to catalog →</button></form></div>
      <div v-if="receipt" class="modal-backdrop"><article class="receipt"><button class="close" @click="receipt=null">×</button><div class="receipt-brand"><b>Vendora<span>X</span></b><small>Northstar Market · Downtown</small></div><h2>Payment successful</h2><p>{{receipt.invoiceNo}} · {{receipt.createdAt}}</p><p class="receipt-meta">Customer: {{receipt.customer}}<br>Cashier: {{receipt.cashier || '—'}}<br>Payment: {{receipt.payment}} {{receipt.reference ? '· ' + receipt.reference : ''}}</p><div v-for="line in receipt.lines" :key="line.id" class="receipt-line"><span><b>{{line.quantity}} × {{line.name}}</b><small>{{money(line.price)}} each</small></span><b>{{money(line.quantity * line.price)}}</b></div><div class="receipt-breakdown"><p><span>Subtotal</span><b>{{money(receipt.subtotal)}}</b></p><p><span>Tax</span><b>{{money(receipt.tax)}}</b></p><p v-if="receipt.discount"><span>Discount</span><b>−{{money(receipt.discount)}}</b></p></div><div class="receipt-total"><span>Total paid via {{receipt.payment}}</span><b>{{money(receipt.total)}}</b></div><button class="new-sale" @click="printReceipt">Print / Save as PDF</button><button class="plain" @click="receipt=null">Start next sale</button></article></div>
    </section>
  </main>
</template>

